import pytest
from flask import url_for

def test_admin_sidebar_collapsible_groups(client, auth_headers):
    # Test that admin sidebar renders collapsible groups and all items when accessing admin console
    response = client.get("/admin/dashboard", headers=auth_headers)
    assert response.status_code == 200
    html = response.get_data(as_text=True)

    # Check for collapsible group headers
    assert "Overview" in html
    assert "Access management" in html
    assert "Collection" in html
    assert "Processing and integrations" in html
    assert "Publishing and content setup" in html

    # Check that overview group is open on Dashboard navigation
    assert 'data-testid="admin-group-overview"' in html
    assert 'open' in html

    # Check that individual destinations and OpenAPI are present
    assert "Admin Dashboard" in html
    assert "Users" in html
    assert "OSINT Sources" in html
    assert "Bots" in html
    assert "Report Item Types" in html
    assert "OpenAPI" in html
<<<END>>>

