import pytest
from playwright.sync_api import Page, expect

def test_admin_sidebar_collapsible_groups(page: Page, authenticated_admin_user):
    page.goto("/admin/dashboard")

    # Check that sidebar is present and uses collapsible groups
    sidebar = page.locator("[data-testid='admin-sidebar']")
    expect(sidebar).toBeVisible()

    # Verify groups exist
    overview_group = page.locator("[data-testid='admin-group-overview']")
    expect(overview_group).toBeVisible()

    access_group = page.locator("[data-testid='admin-group-access-management']")
    expect(access_group).toBeVisible()

    # Verify submenus contain items
    expect(page.locator("[data-testid='admin-menu-Admin Dashboard']")).toBeVisible()
    expect(page.locator("[data-testid='admin-menu-Users']")).toBeVisible()
    expect(page.locator("[data-testid='admin-menu-openapi']")).toBeVisible()

    # Verify active state and auto-opening group on navigation
    page.goto("/admin/users")
    expect(access_group.locator("details")).toHaveAttribute("open", "")
    expect(page.locator("[data-testid='admin-menu-Users']")).toHaveClass(/active/)
