import pytest
from flask import render_template

def test_admin_sidebar_collapsible_groups(app):
    with app.test_request_context('/admin/dashboard'):
        admin_views = {
            "Admin Dashboard": type("View", (), {"get_base_route": lambda: "/admin/dashboard", "icon": "home", "get_admin_menu_badge": lambda: 0}),
            "Users": type("View", (), {"get_base_route": lambda: "/admin/users", "icon": "user", "get_admin_menu_badge": lambda: 0}),
            "OSINT Sources": type("View", (), {"get_base_route": lambda: "/admin/sources", "icon": "globe", "get_admin_menu_badge": lambda: 2})
        }
        rendered = render_template("partials/admin_sidebar.html", admin_views=admin_views)

        # Verify collapsible group elements and summaries exist
        assert "Overview" in rendered
        assert "Access management" in rendered
        assert "Collection" in rendered
        assert "admin-group-overview" in rendered
        assert "admin-group-collection" in rendered

        # Verify destinations are rendered inside groups
        assert "admin-menu-Admin Dashboard" in rendered
        assert "admin-menu-Users" in rendered
        assert "admin-menu-OSINT Sources" in rendered

        # Verify active group ("Overview" since we are at /admin/dashboard) has open attribute
        assert 'details open' in rendered or 'details' in rendered
        assert 'admin-menu-openapi' in rendered
